package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.AddressJsonVO;

class AddressJsonValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of address json of user profile")
  void test_address_json_value_holder_assign_plain_value() {
    Object holder = new Object();
    AddressJsonValueHolder<Object> value = new AddressJsonValueHolder<>(holder);
    Assertions.assertSame(holder, value.addressJson("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAddressJsonValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getAddressJson().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.addressJsonNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getAddressJsonValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getAddressJson().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of address json of user profile")
  void test_address_json_value_holder_assign_value_object() {
    Object holder = new Object();
    AddressJsonValueHolder<Object> value = new AddressJsonValueHolder<>(holder);
    AddressJsonVO vo = AddressJsonVO.from("one");
    Assertions.assertFalse(value.getAddressJsonValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.addressJson(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAddressJsonValue().orElseThrow());
    Assertions.assertSame(holder, value.addressJson(Optional.empty()));
    Assertions.assertFalse(value.getAddressJsonValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.addressJson(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAddressJsonValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of address json of user profile against the original")
  void test_address_json_value_holder_read() {
    Object holder = new Object();
    AddressJsonValueHolder<Object> value = new AddressJsonValueHolder<>(holder);
    AddressJsonVO vo = AddressJsonVO.from("one");
    AddressJsonVO other = AddressJsonVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getAddressJsonValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAddressJson(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAddressJson(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.addressJson(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAddressJson(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAddressJson(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of address json of user profile")
  void test_address_json_value_holder_unset() {
    Object holder = new Object();
    AddressJsonValueHolder<Object> value = new AddressJsonValueHolder<>(holder);
    AddressJsonVO vo = AddressJsonVO.from("one");
    value.addressJson(vo);
    Assertions.assertSame(holder, value.unsetAddressJsonIfMatches("addressJson_other"));
    Assertions.assertTrue(value.getAddressJsonValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAddressJsonIfMatches("addressJson"));
    Assertions.assertFalse(value.getAddressJsonValue().isPresent(),
        "The field name must clear the value");
    value.addressJson(vo);
    Assertions.assertSame(holder, value.unsetAddressJson());
    Assertions.assertFalse(value.getAddressJsonValue().isPresent(), "Unset must clear the value");
  }
}
